mapper.select:
SELECT
    COUNT(*) AS attemptCount,
    COALESCE(SUM(h.transfer_status = 'SUCCESS'), 0) AS successCount,
    COALESCE(SUM(h.transfer_status = 'PARTIAL_LIMIT'), 0) AS partialCount,
    COALESCE(SUM(h.transfer_status = 'FAILED_INSUFFICIENT_FUNDS'), 0) AS failedCount,
    COALESCE(SUM(h.amount), 0) AS totalSavedAmount,
    (

        SELECT COALESCE(MAX(streak.days), 0)
        FROM (
            SELECT COUNT(*) AS days
            FROM (
                SELECT DATE_SUB(
                           s.transacted_at,
                           INTERVAL ROW_NUMBER() OVER (ORDER BY s.transacted_at) DAY
                       ) AS grp
                FROM auto_saving_history s
                    JOIN money_box smb ON s.money_box_id = smb.money_box_id
                WHERE smb.user_id = #{userId}
                    AND s.transacted_at >= #{startDate}
                    AND s.transacted_at <= #{endDate}
                    AND s.transfer_status <> 'FAILED_INSUFFICIENT_FUNDS'
            ) grouped
            GROUP BY grouped.grp
        ) streak
    ) AS maxStreak
FROM auto_saving_history h
    JOIN money_box mb ON h.money_box_id = mb.money_box_id
WHERE mb.user_id = #{userId}
    AND h.transacted_at >= #{startDate}
    AND h.transacted_at <= #{endDate}
